def eqdf_priority(job, alpha):
    return job.d - alpha * job.task.C

# Scheduler: select min eqdf_priority

def optimal_alpha(task_set):
    low, high = 0, 1
    while high - low > 1e-6:
        mid = (low + high) / 2
        if schedulable(task_set, mid):
            low = mid
        else:
            high = mid
    return low
